from common import *
add('3.8.1',r'Chứng minh theo định nghĩa khai triển ở cột đầu, quy nạp theo cấp $n$. Cấp 1 là tính cộng của số thực. Giả sử $A,B,C$ giống nhau ngoài cột $p$, với cột $p$ của $A$ bằng tổng hai cột tương ứng. Nếu $p=1$, các minor ở cột đầu giống nhau và $a_{i1}=b_{i1}+c_{i1}$; tách tổng khai triển cho $\det A=\det B+\det C$. Nếu $p>1$, các hệ số ở cột đầu giống nhau, còn mỗi bộ ba minor cấp $n-1$ thỏa giả thiết cộng ở một cột. Áp dụng quy nạp cho các minor rồi tách tổng khai triển cũng cho kết quả. Không dùng tính tuyến tính đang cần chứng minh làm giả thiết.')
add('3.8.2',r'Đưa hàng ở vị trí $q$ lên vị trí $p$ bằng $q-p$ lần đổi hai hàng kề: đổi $(q-1,q),(q-2,q-1),\ldots,(p,p+1)$. Hàng ban đầu ở $p$ lúc này ở vị trí $p+1$; đưa nó xuống vị trí $q$ bằng $q-p-1$ lần đổi kề. Các hàng ở giữa trở lại vị trí cũ, hai hàng đầu cuối đã đổi cho nhau. Tổng số đổi là $(q-p)+(q-p-1)=2(q-p)-1$, luôn lẻ.')
add('3.8.3',r'Cấp 1: $\det([ua])=ua=u\det([a])$. Giả sử công thức đúng cấp $n-1$. Theo định nghĩa khai triển cột đầu, $$\det(uA)=\sum_i(-1)^{i+1}(ua_{i1})\det(uA_{i1}).$$ Dùng quy nạp cho từng minor: $\det(uA_{i1})=u^{n-1}\det A_{i1}$. Rút $u^n$ khỏi tổng, được $u^n\sum_i(-1)^{i+1}a_{i1}\det A_{i1}=u^n\det A$. Lập luận không chia cho $u$, nên đúng cả $u=0$.')
save()
